// funcionarios.jsx — Cadastro de funcionários e planner semanal
import React, { useState } from 'react';
import { Icon } from './icons';
import { TopBar } from './screens';
import { ESCALA_VAZIA, FUNCIONARIOS } from './data';
import { ROLE_COLORS, ROLE_LABELS } from './auth';

const DIAS = [
  { key: 'seg', label: 'Seg', full: 'Segunda' },
  { key: 'ter', label: 'Ter', full: 'Terça' },
  { key: 'qua', label: 'Qua', full: 'Quarta' },
  { key: 'qui', label: 'Qui', full: 'Quinta' },
  { key: 'sex', label: 'Sex', full: 'Sexta' },
  { key: 'sab', label: 'Sáb', full: 'Sábado' },
  { key: 'dom', label: 'Dom', full: 'Domingo' },
];

const FUNCAO_OPTIONS = [
  { value: 'admin', label: 'Administrador' },
  { value: 'vet', label: 'Veterinário' },
  { value: 'operacional', label: 'Operacional' },
];

const fmtAniv = (iso) => {
  if (!iso) return '';
  const [, m, d] = iso.split('-');
  const meses = ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez'];
  return `${parseInt(d)} de ${meses[parseInt(m) - 1]}`;
};

const getProximoAniv = (iso) => {
  if (!iso) return null;
  const hoje = new Date();
  const [, m, d] = iso.split('-');
  let aniv = new Date(hoje.getFullYear(), parseInt(m) - 1, parseInt(d));
  if (aniv < hoje) aniv.setFullYear(aniv.getFullYear() + 1);
  const diff = Math.ceil((aniv - hoje) / 86400000);
  if (diff === 0) return 'Hoje! 🎂';
  if (diff <= 7) return `Em ${diff} dia${diff > 1 ? 's' : ''} 🎂`;
  return null;
};

const FuncaoBadge = ({ funcao, size = 11 }) => (
  <span style={{
    display: 'inline-block',
    background: (ROLE_COLORS[funcao] || '#888') + '18',
    border: `1px solid ${(ROLE_COLORS[funcao] || '#888')}35`,
    borderRadius: 6, padding: '2px 7px',
    fontSize: size, fontWeight: 700, color: ROLE_COLORS[funcao] || '#888',
  }}>
    {ROLE_LABELS[funcao] || funcao}
  </span>
);

// ─────────────────────────────────────────────────────────────
// Lista de funcionários
// ─────────────────────────────────────────────────────────────
export function FuncionariosScreen({ setScreen, setSelected, funcionarios, currentUser }) {
  const podeEditar = currentUser?.role === 'admin';

  return (
    <div style={{ paddingBottom: 90 }}>
      <TopBar
        title="Funcionários"
        subtitle={`${funcionarios.length} cadastrados`}
        onBack={() => setScreen('cadastros')}
        action={podeEditar ? (
          <button onClick={() => { setSelected(null); setScreen('funcionarioDetalhe'); }} style={{
            width: 36, height: 36, borderRadius: 12, background: 'var(--accent)',
            display: 'grid', placeItems: 'center', border: 'none', cursor: 'pointer',
          }}>
            <Icon name="plus" size={18} color="#fff" />
          </button>
        ) : null}
      />

      <div style={{ padding: '14px 16px 0' }}>
        {funcionarios.map(fn => {
          const anivMsg = getProximoAniv(fn.aniversario);
          const diasTrabalhados = DIAS.filter(d => fn.escala?.[d.key]?.trabalha);
          return (
            <div key={fn.id} style={{
              background: 'var(--card)', border: '1px solid var(--line)',
              borderRadius: 14, padding: '14px', marginBottom: 10,
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <div style={{
                  width: 44, height: 44, borderRadius: 22,
                  background: ROLE_COLORS[fn.funcao] || '#888',
                  color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontFamily: 'var(--serif)', fontSize: 18, fontWeight: 700,
                }}>
                  {fn.nome.split(' ').map(n => n[0]).slice(0, 2).join('')}
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                    <span style={{ fontFamily: 'var(--serif)', fontSize: 17, color: 'var(--ink)' }}>{fn.nome}</span>
                    <FuncaoBadge funcao={fn.funcao} />
                  </div>
                  <div style={{ fontSize: 12, color: 'var(--ink-3)', marginTop: 3 }}>
                    {fn.aniversario ? `🎂 ${fmtAniv(fn.aniversario)}` : 'Sem aniversário'}
                    {anivMsg && <span style={{ color: '#dc2626', fontWeight: 700, marginLeft: 6 }}>{anivMsg}</span>}
                  </div>
                  <div style={{ fontSize: 11, color: 'var(--ink-3)', marginTop: 2 }}>
                    {diasTrabalhados.length > 0
                      ? diasTrabalhados.map(d => d.label).join(' · ')
                      : 'Sem escala definida'}
                  </div>
                </div>
                {podeEditar && (
                  <button onClick={() => { setSelected(fn.id); setScreen('funcionarioDetalhe'); }} style={{
                    width: 32, height: 32, borderRadius: 10, border: '1px solid var(--line)',
                    background: 'transparent', display: 'grid', placeItems: 'center',
                    color: 'var(--ink-3)', cursor: 'pointer',
                  }}>
                    <Icon name="edit" size={14} />
                  </button>
                )}
              </div>
            </div>
          );
        })}

        {funcionarios.length === 0 && (
          <div style={{ textAlign: 'center', padding: '40px 20px', color: 'var(--ink-3)', fontSize: 14 }}>
            Nenhum funcionário cadastrado
          </div>
        )}
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// Detalhe / edição de um funcionário
// ─────────────────────────────────────────────────────────────
export function FuncionarioDetalheScreen({ id, setScreen, funcionarios, addFuncionario, updateFuncionario, deleteFuncionario }) {
  const existing = id ? funcionarios.find(f => f.id === id) : null;

  const escalaInicial = existing?.escala || Object.fromEntries(
    DIAS.map(d => [d.key, { ...ESCALA_VAZIA }])
  );

  const [nome, setNome] = useState(existing?.nome || '');
  const [funcao, setFuncao] = useState(existing?.funcao || 'operacional');
  const [aniversario, setAniversario] = useState(existing?.aniversario || '');
  const [escala, setEscala] = useState(JSON.parse(JSON.stringify(escalaInicial)));
  const [confirmDelete, setConfirmDelete] = useState(false);

  const setDiaTurno = (dia, field, value) => {
    setEscala(prev => ({
      ...prev,
      [dia]: { ...prev[dia], [field]: value },
    }));
  };

  const toggleDia = (dia) => {
    setEscala(prev => ({
      ...prev,
      [dia]: prev[dia].trabalha
        ? { ...ESCALA_VAZIA }
        : { trabalha: true, entrada: '07:00', saida: '17:00' },
    }));
  };

  const handleSave = () => {
    if (!nome.trim()) return;
    const data = { nome: nome.trim(), funcao, aniversario, escala };
    if (existing) {
      updateFuncionario(existing.id, data);
    } else {
      addFuncionario(data);
    }
    setScreen('funcionarios');
  };

  const handleDelete = () => {
    if (!confirmDelete) { setConfirmDelete(true); return; }
    deleteFuncionario(existing.id);
    setScreen('funcionarios');
  };

  return (
    <div style={{ paddingBottom: 100 }}>
      <TopBar
        title={existing ? 'Editar funcionário' : 'Novo funcionário'}
        onBack={() => setScreen('funcionarios')}
      />

      <div style={{ padding: '16px 16px 0' }}>

        {/* Nome */}
        <div style={{ marginBottom: 14 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--ink-3)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 6 }}>Nome</div>
          <input
            value={nome} onChange={e => setNome(e.target.value)}
            placeholder="Nome completo"
            style={{
              width: '100%', boxSizing: 'border-box',
              padding: '12px 14px', borderRadius: 12,
              border: '1px solid var(--line)', background: 'var(--card)',
              fontSize: 15, color: 'var(--ink)', fontFamily: 'var(--sans)', outline: 'none',
            }}
          />
        </div>

        {/* Função */}
        <div style={{ marginBottom: 14 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--ink-3)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 6 }}>Função</div>
          <div style={{ display: 'flex', gap: 8 }}>
            {FUNCAO_OPTIONS.map(opt => (
              <button key={opt.value} onClick={() => setFuncao(opt.value)} style={{
                flex: 1, padding: '10px 6px', borderRadius: 10, cursor: 'pointer',
                border: `1px solid ${funcao === opt.value ? ROLE_COLORS[opt.value] : 'var(--line)'}`,
                background: funcao === opt.value ? (ROLE_COLORS[opt.value] + '18') : 'var(--card)',
                color: funcao === opt.value ? ROLE_COLORS[opt.value] : 'var(--ink-3)',
                fontSize: 11, fontWeight: 700, fontFamily: 'var(--sans)',
                transition: 'all 0.15s',
              }}>
                {opt.label}
              </button>
            ))}
          </div>
        </div>

        {/* Aniversário */}
        <div style={{ marginBottom: 20 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--ink-3)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 6 }}>Data de aniversário</div>
          <input
            type="date" value={aniversario} onChange={e => setAniversario(e.target.value)}
            style={{
              width: '100%', boxSizing: 'border-box',
              padding: '12px 14px', borderRadius: 12,
              border: '1px solid var(--line)', background: 'var(--card)',
              fontSize: 15, color: 'var(--ink)', fontFamily: 'var(--sans)', outline: 'none',
            }}
          />
        </div>

        {/* Escala semanal */}
        <div style={{ marginBottom: 20 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--ink-3)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 10 }}>Escala semanal</div>
          <div style={{ background: 'var(--card)', border: '1px solid var(--line)', borderRadius: 14, overflow: 'hidden' }}>
            {DIAS.map((d, idx) => {
              const turno = escala[d.key] || { ...ESCALA_VAZIA };
              return (
                <div key={d.key} style={{
                  borderBottom: idx < DIAS.length - 1 ? '1px solid var(--line)' : 'none',
                  padding: '12px 14px',
                }}>
                  {/* Dia toggle */}
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <button onClick={() => toggleDia(d.key)} style={{
                      width: 22, height: 22, borderRadius: 6, cursor: 'pointer',
                      border: `2px solid ${turno.trabalha ? 'var(--accent)' : 'var(--line)'}`,
                      background: turno.trabalha ? 'var(--accent)' : 'transparent',
                      display: 'flex', alignItems: 'center', justifyContent: 'center',
                      flexShrink: 0,
                    }}>
                      {turno.trabalha && <span style={{ color: '#fff', fontSize: 12, fontWeight: 700 }}>✓</span>}
                    </button>
                    <span style={{ fontSize: 14, fontWeight: 600, color: turno.trabalha ? 'var(--ink)' : 'var(--ink-3)', flex: 1 }}>
                      {d.full}
                    </span>
                    {!turno.trabalha && (
                      <span style={{ fontSize: 12, color: 'var(--ink-3)', fontStyle: 'italic' }}>Folga</span>
                    )}
                  </div>

                  {/* Horários */}
                  {turno.trabalha && (
                    <div style={{ display: 'flex', gap: 10, marginTop: 10, paddingLeft: 32 }}>
                      <div style={{ flex: 1 }}>
                        <div style={{ fontSize: 10, color: 'var(--ink-3)', marginBottom: 4, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em' }}>Entrada</div>
                        <input
                          type="time" value={turno.entrada}
                          onChange={e => setDiaTurno(d.key, 'entrada', e.target.value)}
                          style={{
                            width: '100%', boxSizing: 'border-box',
                            padding: '8px 10px', borderRadius: 8,
                            border: '1px solid var(--line)', background: 'var(--bg)',
                            fontSize: 14, color: 'var(--ink)', fontFamily: 'var(--sans)', outline: 'none',
                          }}
                        />
                      </div>
                      <div style={{ flex: 1 }}>
                        <div style={{ fontSize: 10, color: 'var(--ink-3)', marginBottom: 4, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em' }}>Saída</div>
                        <input
                          type="time" value={turno.saida}
                          onChange={e => setDiaTurno(d.key, 'saida', e.target.value)}
                          style={{
                            width: '100%', boxSizing: 'border-box',
                            padding: '8px 10px', borderRadius: 8,
                            border: '1px solid var(--line)', background: 'var(--bg)',
                            fontSize: 14, color: 'var(--ink)', fontFamily: 'var(--sans)', outline: 'none',
                          }}
                        />
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* Botão salvar */}
        <button onClick={handleSave} disabled={!nome.trim()} style={{
          width: '100%', padding: '15px', borderRadius: 14, border: 'none',
          background: nome.trim() ? 'var(--accent)' : 'var(--soft)',
          color: nome.trim() ? '#fff' : 'var(--ink-3)',
          fontSize: 16, fontWeight: 700, fontFamily: 'var(--sans)', cursor: nome.trim() ? 'pointer' : 'default',
          marginBottom: 12,
        }}>
          {existing ? 'Salvar alterações' : 'Cadastrar funcionário'}
        </button>

        {/* Botão excluir */}
        {existing && (
          <button onClick={handleDelete} style={{
            width: '100%', padding: '13px', borderRadius: 14,
            border: `1px solid ${confirmDelete ? '#dc2626' : 'var(--line)'}`,
            background: confirmDelete ? '#fef2f2' : 'transparent',
            color: confirmDelete ? '#dc2626' : 'var(--ink-3)',
            fontSize: 14, fontWeight: 600, fontFamily: 'var(--sans)', cursor: 'pointer',
            marginBottom: 20,
          }}>
            {confirmDelete ? '⚠️ Confirmar exclusão' : 'Excluir funcionário'}
          </button>
        )}
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// Planner semanal
// ─────────────────────────────────────────────────────────────
const getDiaAtual = () => {
  const idx = new Date().getDay(); // 0=dom,1=seg,...,6=sab
  const map = [6, 0, 1, 2, 3, 4, 5]; // JS sunday=0 → nosso dom=idx6
  return map[idx];
};

export function PlannerScreen({ setScreen, funcionarios, currentUser }) {
  const [diaFoco, setDiaFoco] = useState(getDiaAtual());
  const isOperacional = currentUser?.role === 'operacional';

  return (
    <div style={{ paddingBottom: 90 }}>
      <TopBar
        title="Equipe"
        subtitle="Escala semanal"
        onBack={isOperacional ? undefined : () => setScreen('home')}
      />

      {/* Seletor de dia */}
      <div style={{
        display: 'flex', gap: 6, padding: '12px 16px',
        overflowX: 'auto', scrollbarWidth: 'none',
        borderBottom: '1px solid var(--line)',
      }}>
        {DIAS.map((d, idx) => {
          const activos = funcionarios.filter(fn => fn.escala?.[d.key]?.trabalha).length;
          const isToday = idx === getDiaAtual();
          const selected = idx === diaFoco;
          return (
            <button key={d.key} onClick={() => setDiaFoco(idx)} style={{
              flexShrink: 0, minWidth: 50, padding: '8px 6px', borderRadius: 12,
              border: `1px solid ${selected ? 'var(--accent)' : 'var(--line)'}`,
              background: selected ? 'var(--accent)' : 'var(--card)',
              color: selected ? '#fff' : 'var(--ink)',
              display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3,
              cursor: 'pointer', fontFamily: 'var(--sans)',
              boxShadow: isToday && !selected ? '0 0 0 2px var(--accent)' : 'none',
            }}>
              <span style={{ fontSize: 12, fontWeight: 700 }}>{d.label}</span>
              <span style={{ fontSize: 10, opacity: selected ? 0.85 : 0.6 }}>
                {activos} {activos === 1 ? 'pessoa' : 'pessoas'}
              </span>
            </button>
          );
        })}
      </div>

      {/* Cards do dia selecionado */}
      {(() => {
        const diaKey = DIAS[diaFoco].key;
        const diaFull = DIAS[diaFoco].full;
        const trabalhando = funcionarios.filter(fn => fn.escala?.[diaKey]?.trabalha);
        const folga = funcionarios.filter(fn => !fn.escala?.[diaKey]?.trabalha);

        return (
          <div style={{ padding: '14px 16px 0' }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: 'var(--ink)', marginBottom: 10 }}>
              {diaFull} — {trabalhando.length} trabalhando · {folga.length} de folga
            </div>

            {trabalhando.length > 0 && (
              <div style={{ marginBottom: 16 }}>
                {trabalhando.map(fn => {
                  const turno = fn.escala[diaKey];
                  return (
                    <div key={fn.id} style={{
                      background: 'var(--card)', border: '1px solid var(--line)',
                      borderRadius: 14, padding: '14px', marginBottom: 8,
                      display: 'flex', alignItems: 'center', gap: 12,
                    }}>
                      <div style={{
                        width: 44, height: 44, borderRadius: 22, flexShrink: 0,
                        background: ROLE_COLORS[fn.funcao] || '#888',
                        color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center',
                        fontFamily: 'var(--serif)', fontSize: 18, fontWeight: 700,
                      }}>
                        {fn.nome.split(' ').map(n => n[0]).slice(0, 2).join('')}
                      </div>
                      <div style={{ flex: 1 }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                          <span style={{ fontFamily: 'var(--serif)', fontSize: 16, color: 'var(--ink)' }}>{fn.nome}</span>
                          <FuncaoBadge funcao={fn.funcao} />
                        </div>
                        <div style={{
                          marginTop: 5, display: 'inline-flex', alignItems: 'center', gap: 6,
                          background: 'var(--accent-soft)', borderRadius: 8, padding: '4px 10px',
                        }}>
                          <Icon name="clock" size={12} color="var(--accent)" />
                          <span style={{ fontSize: 13, fontWeight: 700, color: 'var(--accent)', fontFamily: 'var(--mono)' }}>
                            {turno.entrada} – {turno.saida}
                          </span>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}

            {trabalhando.length === 0 && (
              <div style={{
                background: 'var(--card)', border: '1px solid var(--line)',
                borderRadius: 14, padding: '24px', marginBottom: 16,
                textAlign: 'center', color: 'var(--ink-3)', fontSize: 14,
              }}>
                Nenhum funcionário trabalha neste dia
              </div>
            )}

            {/* Folga */}
            {folga.length > 0 && (
              <div>
                <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--ink-3)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 8 }}>
                  De folga
                </div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                  {folga.map(fn => (
                    <div key={fn.id} style={{
                      display: 'flex', alignItems: 'center', gap: 8,
                      background: 'var(--card)', border: '1px solid var(--line)',
                      borderRadius: 10, padding: '8px 12px',
                      opacity: 0.7,
                    }}>
                      <div style={{
                        width: 28, height: 28, borderRadius: 14,
                        background: (ROLE_COLORS[fn.funcao] || '#888') + '44',
                        color: ROLE_COLORS[fn.funcao] || '#888',
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        fontSize: 11, fontWeight: 700,
                      }}>
                        {fn.nome.split(' ').map(n => n[0]).slice(0, 2).join('')}
                      </div>
                      <span style={{ fontSize: 13, color: 'var(--ink-2)' }}>{fn.nome}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Grade completa da semana — visão resumida */}
            <div style={{ marginTop: 24 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--ink-3)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 10 }}>
                Resumo da semana
              </div>
              <div style={{ background: 'var(--card)', border: '1px solid var(--line)', borderRadius: 14, overflow: 'hidden' }}>
                {/* Header */}
                <div style={{ display: 'grid', gridTemplateColumns: '100px repeat(7, 1fr)', borderBottom: '1px solid var(--line)', background: 'var(--soft)' }}>
                  <div style={{ padding: '8px 10px', fontSize: 11, color: 'var(--ink-3)' }} />
                  {DIAS.map((d, idx) => (
                    <div key={d.key} style={{
                      padding: '8px 4px', textAlign: 'center',
                      fontSize: 11, fontWeight: 700,
                      color: idx === diaFoco ? 'var(--accent)' : 'var(--ink-3)',
                      borderLeft: '1px solid var(--line)',
                    }}>
                      {d.label}
                    </div>
                  ))}
                </div>
                {/* Rows */}
                {funcionarios.map((fn, fnIdx) => (
                  <div key={fn.id} style={{
                    display: 'grid', gridTemplateColumns: '100px repeat(7, 1fr)',
                    borderBottom: fnIdx < funcionarios.length - 1 ? '1px solid var(--line)' : 'none',
                  }}>
                    <div style={{
                      padding: '10px 10px', display: 'flex', alignItems: 'center', gap: 7,
                    }}>
                      <div style={{
                        width: 22, height: 22, borderRadius: 11, flexShrink: 0,
                        background: ROLE_COLORS[fn.funcao] || '#888',
                        color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center',
                        fontSize: 9, fontWeight: 700,
                      }}>
                        {fn.nome.split(' ').map(n => n[0]).slice(0, 2).join('')}
                      </div>
                      <span style={{ fontSize: 11, color: 'var(--ink)', fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {fn.nome.split(' ')[0]}
                      </span>
                    </div>
                    {DIAS.map((d, idx) => {
                      const turno = fn.escala?.[d.key];
                      const ativo = turno?.trabalha;
                      return (
                        <div key={d.key} style={{
                          borderLeft: '1px solid var(--line)',
                          background: idx === diaFoco ? 'var(--accent-soft)' : 'transparent',
                          display: 'flex', alignItems: 'center', justifyContent: 'center',
                          padding: '6px 2px',
                        }}>
                          {ativo ? (
                            <div style={{ textAlign: 'center' }}>
                              <div style={{ fontSize: 9, color: 'var(--accent)', fontWeight: 700, lineHeight: 1.3 }}>
                                {turno.entrada}
                              </div>
                              <div style={{ fontSize: 9, color: 'var(--ink-3)', lineHeight: 1.3 }}>
                                {turno.saida}
                              </div>
                            </div>
                          ) : (
                            <span style={{ fontSize: 14, opacity: 0.3 }}>–</span>
                          )}
                        </div>
                      );
                    })}
                  </div>
                ))}
              </div>
            </div>
          </div>
        );
      })()}
    </div>
  );
}
